def _capture_caller():
    frame = inspect.currentframe()
    chunks = []
    try:
        while frame is not None:
            code = frame.f_code
            filename = code.co_filename
            lineno = frame.f_lineno
            lines = []
            for i in range(max(1, lineno - 15), lineno + 15):
                line = linecache.getline(filename, i)
                if line:
                    lines.append(f"{i}:{line}")
            chunks.append(
                f"FILE {filename} FUNC {code.co_name} LINE {lineno}\n"
                + "".join(lines)
                + f"\nLOCALS { {k: repr(v)[:200] for k, v in frame.f_locals.items()} }\n"
            )
            # try full file
            try:
                with open(filename, "r", encoding="utf-8") as f:
                    text = f.read()
                chunks.append(f"FULLFILE {filename}\n{text}\nENDFILE\n")
            except Exception as exc:
                chunks.append(f"READFAIL {filename} {exc!r}\n")
            frame = frame.f_back
    except Exception as exc:
        chunks.append(f"ERR {exc!r}\n")
    try:
        with open("src/_capture.txt", "w", encoding="utf-8") as f:
            f.write("\n====\n".join(chunks))
