def shipping_cost(weight_kg, express=False):
    """Return the shipping cost in EUR for a parcel.

    The parcel price consists of a EUR 4.00 base fee and EUR 1.75 for
    each kilogram.  Express delivery doubles that total.  Rounding is
    deliberately performed after applying the express multiplier.
    """
    total = 4.00 + 1.75 * weight_kg
    if express:
        total *= 2
    return round(total, 2)

